<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import axios from 'axios'
const route=useRoute(),data=ref<any>({monitors:[],summary:{}}),error=ref(''),loading=ref(true),busy=ref(false),locked=ref(false),token=ref(typeof route.query.token==='string'?route.query.token:'')
const labels:Record<string,string>={UP:'运行正常',DOWN:'服务故障',DEGRADED:'性能降级',PAUSED:'已暂停',MAINTENANCE:'维护中',PENDING:'等待探测',UNKNOWN:'状态未知'}
const overallLabels:Record<string,string>={UP:'当前运行中服务正常',DOWN:'部分服务发生故障',DEGRADED:'部分服务性能降级',PAUSED:'存在已暂停的服务',MAINTENANCE:'部分服务维护中',PENDING:'等待服务探测数据',UNKNOWN:'暂无足够数据确认服务状态'}
const type=(s:string)=>s==='UP'?'success':s==='DOWN'?'danger':s==='DEGRADED'?'warning':'info'
let version=0,timer:ReturnType<typeof setInterval>|undefined
async function load(quiet=false){const request=++version;busy.value=true;if(!quiet)loading.value=true;error.value='';try{const response=await axios.get(`/api/v1/public/status/${encodeURIComponent(String(route.params.slug))}/`,{headers:token.value?{'X-Status-Token':token.value}:{},timeout:20000});if(request===version){data.value=response.data;locked.value=false}}catch(e:any){if(request===version){data.value={monitors:[],summary:{}};locked.value=e.response?.status===403;error.value=e.response?.data?.detail||'状态加载失败，请重试'}}finally{if(request===version){loading.value=false;busy.value=false}}}
watch(()=>route.fullPath,()=>{token.value=typeof route.query.token==='string'?route.query.token:'';load()})
onMounted(()=>{load();timer=setInterval(()=>{if(!busy.value&&!locked.value)load(true)},30000)})
onBeforeUnmount(()=>{version++;if(timer)clearInterval(timer)})
</script>
<template><main class="status" :style="{'--status-theme':data.theme_color||'#0c6c79'}"><header><div class="brand">H</div><div><h1>{{data.name||'业务服务状态'}}</h1><p>{{data.description||'实时服务可用性状态'}}</p></div><button :disabled="busy" @click="load()">{{busy?'刷新中…':'刷新状态'}}</button></header><el-skeleton v-if="loading" :rows="6" animated/><el-result v-else-if="error" icon="warning" title="无法访问状态页" :sub-title="error"><template #extra><form v-if="locked" class="token-form" @submit.prevent="load()"><el-input v-model="token" type="password" show-password placeholder="请输入状态页访问令牌" aria-label="状态页访问令牌"/><el-button native-type="submit" :loading="busy" type="primary">访问</el-button></form></template></el-result><template v-else><section class="overall" :class="data.overall_status?.toLowerCase()"><div><i></i><div><b>{{overallLabels[data.overall_status]||overallLabels.UNKNOWN}}</b><span>共 {{data.summary.total||0}} 项服务，受影响 {{data.summary.affected||0}} 项</span></div></div><small>更新于 {{new Date(data.updated_at).toLocaleString()}}</small></section><el-empty v-if="!data.monitors.length" description="暂无可展示的探测任务"/><section v-else class="list"><article v-for="m in data.monitors" :key="m.id"><div><b>{{m.name}}</b><span>{{m.business}} · {{m.type}}</span></div><div class="metric"><span>{{m.latency_ms==null?'—':Number(m.latency_ms).toFixed(1)+' ms'}}</span><small>{{m.last_checked_at?new Date(m.last_checked_at).toLocaleString():'尚未探测'}}</small></div><el-tag :type="type(m.status)">{{labels[m.status]||m.status}}</el-tag></article></section><footer>合力数据业务监控系统 · 每 30 秒自动刷新 · 按实际探测结果展示</footer></template></main></template>
<style scoped>.status{--status-theme:#0c6c79;max-width:960px;margin:38px auto;padding:20px;color:#213348}header{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:14px;margin-bottom:28px}.brand{width:44px;height:44px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(145deg,var(--status-theme),#133b61);color:#fff;font-size:25px;font-weight:800}h1{font-size:22px;margin:0}header p{color:#7c8b9c;margin:4px 0 0}button{color:var(--status-theme);background:#fff;border:1px solid #d4dde6;border-radius:6px;padding:8px 14px;cursor:pointer}.overall{display:flex;justify-content:space-between;align-items:center;padding:20px 22px;border:1px solid #cde7da;background:#eff9f4;border-radius:8px;color:#226b4b}.overall>div{display:flex;align-items:center;gap:13px}.overall i{display:block;width:13px;height:13px;border-radius:50%;background:#32a66b;box-shadow:0 0 0 7px #32a66b20}.overall b,.overall span{display:block}.overall span,.overall small{font-size:12px;margin-top:5px}.overall.down{color:#9e3f3f;background:#fff1f1;border-color:#efcece}.overall.down i{background:#d55252}.overall.degraded{color:#8c651d;background:#fff8e9;border-color:#eedda8}.list{margin-top:15px;border:1px solid #dde5ec;border-radius:8px;overflow:hidden;background:#fff}.list article{display:grid;grid-template-columns:1fr 190px 110px;align-items:center;padding:16px 19px;border-bottom:1px solid #e9edf1}.list article:last-child{border:0}.list b,.list span,.list small{display:block}.list article>div>span,.metric small{font-size:11px;color:#8492a2;margin-top:4px}.metric{text-align:right;margin-right:20px}.metric span{font-family:monospace;color:#49647d}footer{text-align:center;color:#9aa5b1;font-size:11px;margin-top:24px}.overall.unknown,.overall.pending,.overall.paused,.overall.maintenance{color:#5a6c83;background:#f2f5f9;border-color:#dce3ec}.overall.unknown i,.overall.pending i,.overall.paused i,.overall.maintenance i{background:#8493a7;box-shadow:0 0 0 7px #8493a720}.token-form{display:flex;gap:10px;max-width:460px;margin:auto}button:disabled{opacity:.6;cursor:wait}@media(max-width:600px){.status{margin:12px auto;padding:14px}header{grid-template-columns:auto 1fr;gap:10px}header>button{grid-column:1/-1}h1{font-size:19px}.overall{align-items:flex-start;gap:14px;flex-direction:column}.list article{grid-template-columns:1fr auto;gap:10px}.metric{grid-row:2;grid-column:1/-1;text-align:left;margin:0}.token-form{flex-direction:column}}
</style>
